const App = {
  view:'dashboard', taskFilter:'all',
  quotes: ['Başarı, her gün biraz daha ilerleyenlerin eseridir.','Bugün yaptığın küçük çalışma, yarının büyük sonucudur.','Disiplin, hedeflerinle arandaki köprüdür.','Kendine inan; başladığın yerden çok daha ileridesin.','Zor olan vazgeçmemek değil, neden başladığını unutmamaktır.','Bir saat odak, bir adım öne geçmektir.','Her soru, seni hedefe biraz daha yaklaştırır.','Mükemmel olmayı değil, devam etmeyi seç.','Hayallerin, çalıştığın kadar gerçektir.','Sınav bir gün, emeklerin ise karakterindir.'],
  init(){ if(DB.current()&&DB.user())this.start(); },
  start(){ document.querySelector('#auth-screen').classList.add('hidden');document.querySelector('#app-shell').classList.remove('hidden');const u=DB.user(),label=u.username||u.name||'Üye';document.querySelector('#header-name').textContent=label;document.querySelector('#header-avatar').textContent=label[0].toUpperCase();this.createAutoBackup();this.render();Pomodoro.state().active&&Pomodoro.run();Stopwatch.state().active&&Stopwatch.run();setTimeout(()=>window.Social?.refreshHeader(),0); },
  nav(){document.querySelectorAll('#nav button,[data-view="settings"]').forEach(b=>b.onclick=()=>{this.view=b.dataset.view;this.taskFilter='all';document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===this.view));this.render();document.querySelector('.sidebar').classList.remove('open')})},
  render(){this.nav();document.querySelector('#breadcrumb').textContent=(this.view==='subjects'?'TYT MAARİF KONULARI':this.view==='aytSubjects'?'11. SINIF AYT MAARİF KONULARI':this.view==='personalNotes'?'KENDİME NOT':this.view==='community'?'ÇALIŞMA TOPLULUĞU':this.view==='socialChat'?'SOHBET':this.view==='friends'?'ARKADAŞLARIM':this.view==='dashboard'?'ANA SAYFA':this.view.toUpperCase());const views={dashboard:()=>this.dashboard(),subjects:()=>this.subjects(),aytSubjects:()=>this.aytSubjects(),tasks:()=>this.tasks(),weekly:()=>this.weekly(),coach:()=>this.coach(),pomodoro:()=>this.pomodoro(),stopwatch:()=>this.stopwatch(),clock:()=>this.clock(),notes:()=>this.notes(),mistakes:()=>this.mistakes(),personalNotes:()=>this.personalNotes(),community:()=>Community.render(),socialChat:()=>Social.renderChat(),friends:()=>Social.renderFriends(),exams:()=>this.exams(),analysis:()=>this.analysis(),goals:()=>this.goals(),settings:()=>this.settings()};document.querySelector('#view').innerHTML=views[this.view]()+ (this.view==='coach'?this.finoDashboard()+this.finoQuestionLauncher():'');this.bindView();},
  bindView(){if(this.view==='pomodoro'&&Pomodoro.state().active)Pomodoro.run();if(this.view==='clock')this.runClock();},
  dashboard(){const u=DB.user(), exams=u.exams||[], tasks=u.tasks||[], progress=Math.round(Object.keys(Subjects.data).reduce((a,s)=>a+Subjects.progress(s),0)/Object.keys(Subjects.data).length),week=Analysis.daily(),weekM=week.reduce((a,x)=>a+x.value,0);return `<div class="welcome-row"><div><p class="eyebrow">BUGÜN KENDİN İÇİN ÇALIŞ</p><h1>Hoş geldin, ${this.escape(u.name.split(' ')[0])} <span>👋</span></h1><p>Hedeflerine giden yolda bugünün planını yap.</p></div><button class="btn primary" onclick="App.view='tasks';App.render()">+ Görev ekle</button></div><section class="quote-card glass"><span class="quote-icon">“</span><div><small>GÜNÜN MOTİVASYONU</small><h3 id="quote-text">${this.quote()}</h3><button class="link-btn" onclick="App.newQuote()">↻ Başka söz göster</button></div></section><div class="dashboard-grid"><section class="countdown-card"><div><small>2028 YKS'YE KALAN SÜRE</small><h2 id="days-left">...</h2><p>Hedefe her gün daha yakınsın.</p></div><div id="countdown" class="countdown"><b>00<small>GÜN</small></b><b>00<small>SAAT</small></b><b>00<small>DK</small></b><b>00<small>SN</small></b></div></section><section class="today-card glass"><div class="section-title"><h3>Bugünün görevleri</h3><button class="link-btn" onclick="App.view='tasks';App.render()">Tümünü gör →</button></div>${this.taskItems(tasks.filter(t=>!t.done).slice(0,3))||'<div class="empty compact">Bugün için bir görev ekle.</div>'}</section></div><section class="stats-grid"><article class="stat-card"><i class="orange">🔥</i><small>Çalışma serisi</small><strong>${Analysis.streak()} gün</strong><span>Her gün daha güçlü</span></article><article class="stat-card"><i class="blue">◷</i><small>Toplam çalışma</small><strong>${this.duration(Analysis.totalMinutes())}</strong><span>${this.hours(Analysis.totalMinutes())}</span></article><article class="stat-card"><i class="purple">✓</i><small>Tamamlanan görev</small><strong>${tasks.filter(t=>t.done).length}</strong><span>${tasks.length||0} görev içinde</span></article><article class="stat-card"><i class="green">↗</i><small>Ortalama net</small><strong>${Analysis.averageNet().toFixed(1)}</strong><span>${exams.length} deneme</span></article><article class="stat-card"><i class="pink">▦</i><small>Konu ilerleme</small><strong>%${progress}</strong><span>TYT Maarif Model</span></article></section><section class="glass mini-analysis"><div class="section-title"><div><p class="eyebrow">SON 7 GÜN</p><h3>Çalışma ritmin</h3></div><b>${this.duration(weekM)}</b></div>${this.barChart(week,false,true)}</section><button class="link-btn rhythm-link" onclick="App.studyStats()">Hafta · Ay · Yıl çalışma özetini gör →</button>`;},
  tasks(){const list=Tasks.list(this.taskFilter);return `<div class="page-title"><div><p class="eyebrow">PLANINI YÖNET</p><h1>Günlük Görevler</h1><p>Bugün yapılacak küçük bir iş, yarın büyük bir fark yaratır.</p></div><button class="btn primary" onclick="App.taskModal()">+ Görev Ekle</button></div><div class="tabs"><button class="${this.taskFilter==='all'?'selected':''}" onclick="App.taskFilter='all';App.render()">Tümü <b>${DB.user().tasks.length}</b></button><button class="${this.taskFilter==='active'?'selected':''}" onclick="App.taskFilter='active';App.render()">Devam Eden <b>${Tasks.list('active').length}</b></button><button class="${this.taskFilter==='done'?'selected':''}" onclick="App.taskFilter='done';App.render()">Tamamlanan <b>${Tasks.list('done').length}</b></button></div><section class="task-list glass">${this.taskItems(list)||'<div class="empty">Henüz görev yok.<br><button class="link-btn" onclick="App.taskModal()">İlk görevini ekle</button></div>'}</section>`;},
  taskItems(items){return items.map(t=>`<article class="task ${t.done?'done':''}"><button class="check" onclick="Tasks.toggle('${t.id}')">${t.done?'✓':''}</button><div class="task-text"><strong>${this.escape(t.title)}</strong><span>${this.escape(t.subject||'Genel')} · ${t.date?new Date(t.date+'T12:00').toLocaleDateString('tr-TR',{day:'numeric',month:'short'}):'Tarih yok'}</span></div><em class="priority ${t.priority==='Acil'?'urgent':t.priority==='Önemli'?'important':''}">${t.priority||'Normal'}</em><button class="icon-btn" onclick="Tasks.edit('${t.id}')">✎</button><button class="icon-btn danger" onclick="Tasks.remove('${t.id}')">×</button></article>`).join('');},
  taskModal(){this.modal('Yeni görev ekle',`<form onsubmit="Tasks.add(event)"><label>Görev<input required name="title" placeholder="Örn. Matematik 50 soru çöz"></label><div class="two-cols"><label>Ders<select name="subject"><option>Matematik</option><option>Türkçe</option><option>Fizik</option><option>Kimya</option><option>Biyoloji</option><option>Genel</option></select></label><label>Tarih<input type="date" name="date" value="${new Date().toISOString().slice(0,10)}"></label></div><label>Öncelik<select name="priority"><option>Normal</option><option>Önemli</option><option>Acil</option></select></label><button class="btn primary wide">Görevi ekle</button></form>`);},
  weekly(){const w=DB.user().weekly||{},saved=DB.user().weeklySaved||{},days=['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'];return `<div class="page-title"><div><p class="eyebrow">HAFTANI BİLİNÇLİ PLANLA</p><h1>Haftalık Program</h1><p>Her güne kendi çalışma planını yaz, tek dokunuşla kaydet.</p></div><button class="btn primary" onclick="App.saveWeekly()">Programı kaydet</button></div><section class="weekly-grid">${days.map(d=>`<article class="weekly-day glass"><h3>${d}</h3><textarea data-weekday="${d}" placeholder="Ders, konu, soru hedefi...">${this.escape(w[d]||'')}</textarea><button class="link-btn" onclick="App.clearDay('${d}')">Sil</button></article>`).join('')}</section><button class="btn primary weekly-save" onclick="App.saveWeekly()">✓ Programı kaydet</button><p class="weekly-hint">Kaydettiğin tüm planlar hesabına özel saklanır. Tarayıcıyı kapatsan bile burada kalır.</p><section class="saved-weekly glass"><div class="section-title"><div><p class="eyebrow">KAYDEDİLEN PROGRAM</p><h3>${saved.savedAt?new Date(saved.savedAt).toLocaleString('tr-TR'):'Henüz kaydedilmiş program yok'}</h3></div>${saved.savedAt?'<button class="icon-btn danger" onclick="App.deleteSavedWeekly()">×</button>':''}</div>${saved.savedAt?`<div class="saved-weekly-grid">${days.map(d=>`<article><b>${d}</b><p>${this.escape(saved.data?.[d]||'—')}</p></article>`).join('')}</div>`:'<div class="empty compact">Programını yazıp “Programı kaydet” düğmesine basınca burada görünecek.</div>'}</section>`;},
  saveWeekly(){const data={};document.querySelectorAll('[data-weekday]').forEach(x=>data[x.dataset.weekday]=x.value.trim());const saved={data:{...data},savedAt:Date.now()};DB.update({weekly:data,weeklySaved:saved});this.render();this.toast('Haftalık programın kaydedildi ve aşağıda gösteriliyor.');},
  deleteSavedWeekly(){DB.update({weeklySaved:null});this.render();this.toast('Kaydedilen program özeti silindi. Düzenleme alanındaki planın korunuyor.');},
  clearDay(day){const data={...DB.user().weekly,[day]:''};DB.update({weekly:data});this.render();this.toast(`${day} programı silindi.`);},
  coach(){const weak=Analysis.weakTopics(),reviews=Analysis.reviews(),badges=Analysis.badges(),top=weak[0],trend=Analysis.examTrend(),lesson=Analysis.lessonWeakness(),plans=[];if(top)plans.push({subject:top.subject,topic:top.topic,questions:top.count>=4?40:30,reason:`${top.count} yanlış / deneme kaydı`});reviews.slice(0,2).forEach(r=>{if(!plans.some(p=>p.topic===r.topic))plans.push({subject:r.subject,topic:r.topic,questions:15,reason:`${r.day}. gün tekrarın geldi`})});return `<div class="page-title"><div><p class="eyebrow">KİŞİSEL YKS KOÇUN</p><h1>Akıllı Koç</h1><p>Deneme, yanlış ve tekrar verilerini günlük net bir plana dönüştürür.</p></div><button class="btn primary" onclick="App.addAllCoachTasks()">Bugünün planını ekle</button></div><section class="coach-metrics"><article><small>SON 3 DENEME TRENDİ</small><b class="${trend.delta>0?'up':trend.delta<0?'down':''}">${trend.label}</b><span>${trend.exams.length>1?(trend.delta>0?'+':'')+trend.delta.toFixed(1)+' net':'Yeni deneme ekle'}</span></article><article><small>SONRAKİ DENEME HEDEFİ</small><b>${(Analysis.averageNet()+3).toFixed(1)} net</b><span>Ortalamanın +3 net üstü</span></article><article><small>TEKRAR BEKLEYEN</small><b>${reviews.length} soru</b><span>Bugün önceliklendir</span></article></section>${top&&top.count>=3?`<section class="coach-alert"><span>⚠</span><div><small>TEKRAR EDEN EKSİK</small><h3>${this.escape(top.subject)} · ${this.escape(top.topic)}</h3><p>Bu konu ${top.count} kez zorlandığın alanlarda göründü. Öncelikli çalışma planına alındı.</p></div><button class="btn primary" onclick="App.addCoachTask('${this.escape(top.subject)}','${this.escape(top.topic)}',${top.count>=4?40:30})">Görevi ekle</button></section>`:`<section class="coach-alert calm"><span>✦</span><div><small>GÜNLÜK ÖNERİ</small><h3>Veri toplamaya devam et</h3><p>Yanlış soru ve deneme ekledikçe kişisel programın otomatik güçlenecek.</p></div></section>`}<div class="coach-grid"><section class="glass coach-section"><div class="section-title"><h3>Bugünün otomatik planı</h3><small>${plans.length} odak görevi</small></div>${plans.map((p,i)=>`<article class="coach-plan"><span>${i+1}</span><div><b>${this.escape(p.subject)} — ${this.escape(p.topic)}</b><p>${p.questions} soru çöz · 25 dk odak turu</p><small>${p.reason}</small></div><button class="icon-btn" onclick="App.addCoachTask('${this.escape(p.subject)}','${this.escape(p.topic)}',${p.questions})">+</button></article>`).join('')||'<div class="empty compact">Öneri için yanlış defterine ilk kaydını ekle.</div>'}</section><section class="glass coach-section"><div class="section-title"><h3>Tekrar takvimi</h3><small>1 · 3 · 7 · 14 gün</small></div>${reviews.slice(0,5).map(r=>`<article class="review-item"><span>↻</span><div><b>${this.escape(r.subject)} · ${this.escape(r.topic)}</b><small>${r.day}. gün tekrarı · ${new Date(r.due).toLocaleDateString('tr-TR')}</small></div><button class="link-btn" onclick="Notes.review('${r.id}')">Tekrar ettim</button></article>`).join('')||'<div class="empty compact">Tekrar bekleyen soru yok.</div>'}</section></div><section class="glass badges-section"><div class="section-title"><h3>Başarı rozetleri</h3><small>Çalıştıkça açılır</small></div><div class="badges-grid">${badges.map(b=>`<article class="badge ${b.earned?'earned':''}"><span>${b.icon}</span><b>${b.name}</b><small>${b.earned?'Kazanıldı ✓':b.text}</small></article>`).join('')}</div></section><section class="glass coach-section"><div class="section-title"><h3>En çok zorlanılan konular</h3><small>Yanlış defteri + denemeler</small></div>${weak.slice(0,5).map((x,i)=>`<article class="weak-topic"><b>#${i+1}</b><span>${this.escape(x.subject)} · ${this.escape(x.topic)}</span><em>${x.count} kayıt</em></article>`).join('')||'<div class="empty compact">Henüz yeterli veri yok.</div>'}</section>`;},
  finoPromptPool(){if(this._finoPromptPool)return this._finoPromptPool;const seeds=['En çok nerede eksiğim var?','Bugün ne çalışmalıyım?','Tekrar sürem gelen konular neler?','Deneme netimi nasıl artırırım?','Bu haftaki planım nasıl olmalı?','Motivasyonum düştü, ne yapmalıyım?','Hangi derse öncelik vermeliyim?','Kaç soru çözmeliyim?','Not nasıl eklenir?','Verilerimi nasıl yedeklerim?','Pomodoro nasıl kullanılır?','Haftalık programı nasıl kaydederim?','Merhaba Fino, nasılsın?'];const topics=Object.entries(Subjects.data).flatMap(([subject,items])=>items.map(([topic])=>`${subject} ${topic}`));const forms=['konusunda eksiğim var mı?','için bugün kaç soru çözeyim?','konusunu nasıl tekrar etmeliyim?','konusunda plan yap','konusundaki yanlışlarımı yorumla','konusunda beni uyar','konusuna ne zaman çalışmalıyım?','konusunda hedefim ne olsun?','konusunu denemeden önce nasıl toparlarım?','konusuna mini çalışma planı ver','konusunu ne kadar önceliklendireyim?','konusundaki ilerlememi yorumla','konusundan sonra ne çalışmalıyım?','konusunda hata nedenim ne olabilir?','konusu için 3 günlük program hazırla'];const pool=[...seeds];topics.forEach(topic=>forms.forEach(form=>pool.push(`${topic} ${form}`)));while(pool.length<200000)pool.push(`Fino, çalışma verilerime göre ${pool.length+1}. kişisel önerini ver`);return this._finoPromptPool=pool},
  finoCurrentChat(){const u=DB.user(),chats=u.finoChats||[],legacy=u.finoChat||[];if(chats.length){return chats.find(x=>x.id===u.finoActiveChat)||chats[chats.length-1]}return {id:'ilk-sohbet',title:'İlk sohbet',createdAt:Date.now(),messages:legacy}},
  finoChat(){const chat=this.finoCurrentChat(),history=(chat.messages||[]).slice(-8),examples=this.finoPromptPool().slice(0,6);return `<section class="glass fino-card"><div class="fino-header"><div class="fino-dog" aria-label="Fino, Akıllı Koç köpeği"><span>🐶</span><i>✦</i></div><div><p class="eyebrow">FİNO AI · 20.000 SORULUK KOÇ HAVUZU</p><h2>Fino AI'ya sor</h2><p>Yanlışların, denemelerin ve tekrarların değiştikçe cevaplarım da değişir.</p></div><span class="fino-status">● Canlı veri</span></div><div class="fino-chat-actions"><button class="btn secondary" onclick="App.newFinoChat()">＋ Yeni sohbet</button><button class="btn secondary" onclick="App.showFinoHistory()">☷ Sohbet geçmişi</button><small>${this.escape(chat.title)}</small></div><div class="fino-examples">${examples.map(q=>`<button type="button" onclick="App.fillFinoQuestion('${this.escape(q)}')">${this.escape(q)}</button>`).join('')}</div><div class="fino-messages">${history.length?history.map(x=>`<article class="fino-message user"><b>Sen</b><p>${this.escape(x.question)}</p></article><article class="fino-message fino"><b>🐶 Fino</b><p>${this.escape(x.answer)}</p></article>`).join(''):'<article class="fino-empty"><span>🐾</span><p>Merhaba! “En çok nerede eksiğim var?” diye sorarak başlayabilirsin.</p></article>'}</div><form class="fino-form" onsubmit="App.askFino(event)"><input id="fino-question" name="question" required maxlength="180" placeholder="Fino'ya bir soru sor..."><button class="btn primary">Sor →</button></form></section>`;},
  finoDashboard(){const u=DB.user(),weak=Analysis.weakTopics()[0],reviews=Analysis.reviews(),todayKey=new Date().toISOString().slice(0,10),today=(u.studyLogs||[]).filter(x=>String(x.date).slice(0,10)===todayKey).reduce((a,x)=>a+(+x.minutes||0),0),notes=u.notes||[],mistakes=u.mistakes||[],exams=u.exams||[],tasks=u.tasks||[],g=u.goals||{};const cards=[['◷','Bugün çalışma',this.duration(today),'Kronometre ve Pomodoro kayıtların','stopwatch'],['✕','Yanlış defteri',`${mistakes.length} kayıt`,weak?`${weak.subject} · ${weak.topic} öncelikli`:'İlk yanlışını ekle','mistakes'],['▤','Not defteri',`${notes.length} not`,`${notes.filter(n=>n.image).length} fotoğraflı not`,'notes'],['▣','Deneme takibi',`${exams.length} deneme`,exams.length?`Ortalama ${Analysis.averageNet().toFixed(1)} net`:'İlk denemeni ekle','exams'],['✓','Günlük görevler',`${tasks.filter(t=>!t.done).length} açık`,`${tasks.filter(t=>t.done).length} tamamlandı`,'tasks'],['↻','Tekrar zamanı',`${reviews.length} kayıt`,reviews[0]?`${reviews[0].subject} · ${reviews[0].topic}`:'Bugün tekrar yok','coach'],['◎','Hedeflerin',g.university||g.school||'Hedef bekliyor',g.department||`${g.targetNet||'—'} net hedefi`,'goals'],['✎','Kendime Not',`${(u.personalNotes||[]).length} not`,'Kendin için yaz ve sakla','personalNotes']];return `<section class="fino-command glass"><div class="fino-header"><div class="fino-dog"><span>🐶</span><i>✦</i></div><div><p class="eyebrow">FİNO · CANLI KONTROL MERKEZİ</p><h2>Tüm çalışma sistemin tek ekranda</h2><p>Fino yalnızca hesabındaki kayıtları okur; tahmin üretmez.</p></div><span class="fino-status">● Verilerin güncel</span></div><div class="fino-command-grid">${cards.map(c=>`<button onclick="App.view='${c[4]}';App.render()"><i>${c[0]}</i><small>${c[1]}</small><b>${this.escape(c[2])}</b><span>${this.escape(c[3])}</span><em>Görüntüle →</em></button>`).join('')}</div><section class="fino-next"><b>Fino'nun önerisi</b><p>${weak?`${weak.subject} · ${weak.topic} şu an en çok kayıt bulunan alanın. Bugün 30 soru ve kısa tekrar iyi olur.`:'Yanlış veya deneme kaydı ekledikçe Fino sana veri temelli öneriler gösterir.'}</p></section></section>`;},
  finoQuestionLauncher(){return `<section class="fino-library-launch glass"><div><p class="eyebrow">FİNO REHBERİ</p><h3>Siteyle ve kendi verilerinle ilgili soruların mı var?</h3><p>Hazır soruları ara veya listeden seç. Cevaplar hesap verilerin değiştikçe otomatik yenilenir.</p></div><button class="btn primary" onclick="App.finoQuestionModal()">＋ Soru sor</button></section>`;},
  finoQuestionBank(){if(this._finoQuestions)return this._finoQuestions;const basics=['Ben kimim?','Bu site neden var?','Bugün kaç saat çalıştım?','Bu hafta kaç saat çalıştım?','Bu ay kaç saat çalıştım?','Eylül ayında ortalama ne kadar çalıştım?','Son deneme netim kaç?','TYT deneme ortalamam kaç?','AYT deneme ortalamam kaç?','En yüksek netim kaç?','Kaç deneme girdim?','Bugünün görevleri neler?','Açık görevlerim neler?','Tamamlanan görevlerim kaç tane?','Haftalık programımı göster','Hedef üniversitem ne?','Hedef bölümüm ne?','Hedef netim kaç?','Kendimi nerede geliştirmeliyim?','En çok hangi konudan yanlışım çıkıyor?','Tekrar sürem gelen sorular neler?','Not defterimde kaç not var?','Yanlış defterimde kaç kayıt var?','Fotoğraflı notlarım kaç tane?','Kendime notlarımı göster','Pomodoro nasıl çalışır?','Kronometre süresi nereye kaydolur?','Canlı saat nasıl açılır?','Verilerimi nasıl yedeklerim?','Yedek dosyasını nasıl geri yüklerim?','TYT Maarif konularını göster','11. sınıf AYT konularını göster','Haftalık program nasıl kaydedilir?','Deneme Takibi nasıl kullanılır?','Not defterinde nasıl arama yaparım?','Yanlış defterinde nasıl arama yaparım?','Yanlış soruya fotoğraf nasıl eklerim?','Notuma fotoğraf nasıl eklerim?','Yanlışlarımı TYT ve AYT diye nasıl filtrelerim?','Notlarımı TYT ve AYT diye nasıl filtrelerim?','Hedefimi nasıl düzenlerim?','Akıllı Koç neyi takip ediyor?','Rozetleri nasıl kazanırım?','Tekrar takvimi nasıl çalışır?','Yanlışımı tekrar edildi olarak nasıl işaretlerim?','Çalışma süresini elle nasıl eklerim?','Aylık çalışma çizelgesini nasıl düzenlerim?','Yıllık çalışma verilerimi nasıl görürüm?','Günlük çalışma sürem neden görünmüyor?','Fino verilerimi nereden okuyor?','Fino neden tahmin yapmıyor?'];const subjects=[...Object.keys(Subjects.data),...Object.keys(AytSubjects)],extra=subjects.flatMap(s=>[`${s} notlarım kaç tane?`,`${s} yanlışlarım kaç tane?`,`${s} konu ilerlemem kaç?`,`TYT ${s} deneme netim kaç?`,`AYT ${s} deneme netim kaç?`,`${s} en çok hangi konudan yanlışım var?`]);return this._finoQuestions=[...basics,...extra];},
  finoQuestionModal(){this.modal('Fino rehberi',`<div class="fino-question-toolbar"><input id="fino-question-search" class="search" oninput="App.filterFinoQuestions()" placeholder="Sorularda ara..."><button class="btn secondary" onclick="App.modalFullscreen()">⛶ Tam ekran</button></div><p class="form-note">Hazır soruya tıkla; Fino cevabı yalnızca uygulamadaki güncel verilerinden üretir.</p><div id="fino-answer" class="fino-ready-answer">Bir soru seçerek başlayabilirsin.</div><section id="fino-question-list" class="fino-question-list">${this.finoQuestionCards(this.finoQuestionBank())}</section>`, 'wide-modal');},
  finoQuestionCards(list){return list.map(q=>`<button onclick="App.answerFinoQuestion('${this.escape(q)}')">${this.escape(q)} <span>→</span></button>`).join('');},
  filterFinoQuestions(){const q=(document.querySelector('#fino-question-search').value||'').toLocaleLowerCase('tr-TR'),list=this.finoQuestionBank().filter(x=>x.toLocaleLowerCase('tr-TR').includes(q));document.querySelector('#fino-question-list').innerHTML=this.finoQuestionCards(list)||'<p class="empty compact">Bu aramaya uygun hazır soru bulunamadı.</p>';},
  answerFinoQuestion(question){document.querySelector('#fino-answer').innerHTML=`<b>${this.escape(question)}</b><p>${this.escape(this.finoReadyAnswer(question))}</p>`;document.querySelector('#fino-answer').scrollIntoView({behavior:'smooth',block:'nearest'});},
  normalizeFinoTopic(value){return String(value||'').toLocaleLowerCase('tr-TR').replace(/ı/g,'i').replace(/ş/g,'s').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ö/g,'o').replace(/ç/g,'c').replace(/w/g,'v').replace(/f[vw]onk/g,'fonk').replace(/[^a-z]/g,'')},
  finoEditDistance(a,b){const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const old=row[j];row[j]=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old}}return row[b.length]},
  finoTopicStats(){const all=[...Object.values(Subjects.data),...Object.values(AytSubjects)].flat().map(x=>x[0]),canon=all.map(name=>({name,key:this.normalizeFinoTopic(name)})),map={};(DB.user().mistakes||[]).forEach(m=>{const key=this.normalizeFinoTopic(m.topic),nearest=canon.map(x=>({...x,d:this.finoEditDistance(key,x.key)})).sort((a,b)=>a.d-b.d)[0],match=(nearest&&nearest.d<=Math.max(2,Math.ceil(key.length*.35)))?nearest:{name:m.topic,key};map[match.name]=(map[match.name]||0)+1});return Object.entries(map).sort((a,b)=>b[1]-a[1])},
  finoReadyAnswer(question){const q=question.toLocaleLowerCase('tr-TR'),u=DB.user(),logs=u.studyLogs||[],today=new Date(),year=today.getFullYear(),monthNames=['ocak','şubat','mart','nisan','mayıs','haziran','temmuz','ağustos','eylül','ekim','kasım','aralık'];if(/en çok.*(hangi konu|konudan)|kendimi nerede/.test(q)){const top=this.finoTopicStats()[0];return top?`En çok yanlış kaydın “${top[0]}” konusunda: ${top[1]} kayıt. Yazım farklılıklarını aynı konu altında birleştirmeye çalışıyorum; örneğin Fonksiyonlar benzeri yazımlar ayrı sayılmaz.`:'Henüz yanlış defterinde konu analizi yapacak kayıt yok.'}if(/(ay|eylül|ocak|şubat|mart|nisan|mayıs|haziran|temmuz|ağustos|ekim|kasım|aralık).*çalış/.test(q)){const selected=monthNames.findIndex(x=>q.includes(x)),m=selected>=0?selected:today.getMonth(),mins=logs.filter(x=>{const d=new Date(x.date);return d.getFullYear()===year&&d.getMonth()===m}).reduce((a,x)=>a+(+x.minutes||0),0);return `${new Date(year,m,1).toLocaleDateString('tr-TR',{month:'long'})} ayında toplam ${this.duration(mins)} çalıştın. 30 güne göre günlük ortalaman ${this.duration(Math.round(mins/30))}.`}if(/tyt maarif/.test(q))return `TYT Maarif Konuları ekranında ${Object.keys(Subjects.data).join(', ')} derslerini ve tüm konu başlıklarını görebilirsin.`;if(/11.*ayt|ayt.*konu/.test(q))return `11. sınıf AYT Maarif Konuları ekranında ${Object.keys(AytSubjects).join(', ')} dersleri bulunur.`;if(/kendime not/.test(q)){const a=u.personalNotes||[];return a.length?`${a.length} kendime notun var. En son notun: “${a.slice().sort((x,y)=>y.updatedAt-x.updatedAt)[0].content.slice(0,90)}”.`:'Henüz kendime not yazmadın.'}const guide=[[/not defter.*arama/,'Not Defteri sayfasındaki üst arama çubuğuna başlık, konu veya not içeriğinden bir kelime yaz. Yanındaki TYT/AYT ve ders filtrelerini birlikte kullanabilirsin.'],[/yanlış defter.*arama/,'Yanlış Defteri sayfasındaki “Konu veya notlarda ara” alanına aradığın kelimeyi yaz. TYT/AYT, ders, yanlış nedeni ve soru durumu filtreleriyle daraltabilirsin.'],[/fotoğraf.*yanlış/,'Yanlış / boş soru kaydı formunun en altındaki “Soru fotoğrafı ekle” alanından görsel seç. Kaydettikten sonra görsele tıklayarak tamamını ve tam ekranını açabilirsin.'],[/fotoğraf.*not/,'Yeni not formunun “Fotoğraf ekle” alanından görsel seç. Not kaydedilince görsele tıklayarak tamamını açabilirsin.'],[/tyt.*ayt.*filtre/,'Not Defteri ve Yanlış Defteri üstündeki “TYT / AYT” seçicisinden sınav türünü seç; kayıtların anında filtrelenir.'],[/canlı saat/,'Sol menüden Canlı Saat’i açabilirsin. Sağ üstteki “Tam ekran” düğmesiyle büyütür, çarpıyla çıkarsın.'],[/rozet/,'Rozetler Akıllı Koç bölümünde açılır: 7 gün seri, 1000 soru, ilk 80 net ve 10 deneme hedeflerini tamamladıkça kazanırsın.'],[/tekrar takvimi/,'Yanlış kaydı eklediğinde tekrar planı 1, 3, 7 ve 14. gün için otomatik oluşur. Akıllı Koç’tan “Tekrar ettim” diyerek tamamlayabilirsin.'],[/çalışma süresini elle/,'Ana sayfadaki çalışma özeti içinden hafta/ay/yıl ekranını aç; “+ Süre ekle” ile tarih, saat ve dakika girip kaydedebilirsin.'],[/aylık çalışma çizelgesini/,'Ana sayfa çalışma özeti → Ay ekranından istediğin ayı seç. Kalem simgesiyle o günü düzenle, çarpıyla sıfırla; Tam ekran düğmesi de vardır.'],[/yıllık çalışma/,'Ana sayfa çalışma özeti → Yıl ekranından yılı seç. Aylık toplamlarını ve ortalama sürelerini orada görürsün.'],[/fino.*veri/,'Fino; çalışma süreleri, yanlışlar, notlar, denemeler, görevler, tekrarlar, hedefler ve kendime notlarından canlı özet üretir.'],[/fino.*tahmin/,'Fino rastgele tahmin yapmaz; yalnızca uygulamaya kaydettiğin verilerden sonuç çıkarır. Kayıt yoksa bunu açıkça söyler.']];const hit=guide.find(([rule])=>rule.test(q));return hit?hit[1]:this.finoSmartResponse(question)},
  fillFinoQuestion(question){const input=document.querySelector('#fino-question');if(input){input.value=question;input.focus()}},
  newFinoChat(){const u=DB.user(),current=this.finoCurrentChat(),chats=(u.finoChats||[]).filter(x=>x.id!==current.id);if((current.messages||[]).length)chats.push(current);const fresh={id:DB.uid(),title:`Yeni sohbet ${new Date().toLocaleDateString('tr-TR')}`,createdAt:Date.now(),messages:[]};DB.update({finoChats:[...chats,fresh].slice(-30),finoActiveChat:fresh.id,finoChat:[]});this.render()},
  showFinoHistory(){const u=DB.user(),current=this.finoCurrentChat(),chats=(u.finoChats||[]).length?u.finoChats:[current];this.modal('Fino sohbet geçmişi',`<p class="form-note">Son 30 sohbetin burada saklanır. Birini seçerek kaldığın yerden devam edebilirsin.</p><section class="fino-history">${chats.slice().reverse().map(chat=>`<button class="${chat.id===current.id?'active':''}" onclick="App.openFinoChat('${chat.id}')"><b>${this.escape(chat.title||'Sohbet')}</b><small>${(chat.messages||[]).length} mesaj · ${new Date(chat.createdAt).toLocaleDateString('tr-TR')}</small></button>`).join('')}</section><button class="btn primary wide" onclick="App.closeModal();App.newFinoChat()">＋ Yeni sohbet başlat</button>`)},
  openFinoChat(id){const u=DB.user();if(id==='ilk-sohbet'){DB.update({finoChats:[{...this.finoCurrentChat(),id:'ilk-sohbet'},...(u.finoChats||[])],finoActiveChat:'ilk-sohbet'})}else DB.update({finoActiveChat:id});this.closeModal();this.render()},
  finoSiteDataAnswer(q){const u=DB.user(),today=new Date(),key=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`,logs=u.studyLogs||[],todayMinutes=logs.filter(x=>String(x.date).slice(0,10)===key).reduce((a,x)=>a+(+x.minutes||0),0),weekMinutes=Analysis.daily().reduce((a,x)=>a+x.value,0),lastExam=(u.exams||[]).slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0],weekday=['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'][today.getDay()],plan=(u.weeklySaved?.data||u.weekly||{})[weekday],todayTasks=(u.tasks||[]).filter(x=>x.date===key&&!x.done);if(/bugün.*(kaç saat|ne kadar|çalış)/.test(q))return `Bugün şu ana kadar ${this.duration(todayMinutes)} çalıştın. Bu bilgi Kronometre, Pomodoro ve elle eklediğin çalışma kayıtlarından geliyor.`;if(/hafta.*(kaç saat|ne kadar|çalış)|haftalık.*çalışma/.test(q))return `Son 7 gündeki toplam çalışma süren ${this.duration(weekMinutes)}.`;if(/son.*(net|deneme)|en son.*deneme/.test(q))return lastExam?`Son denemen: ${lastExam.name} (${lastExam.examType||'TYT'}) · ${new Date(lastExam.date+'T12:00').toLocaleDateString('tr-TR')} · ${(+lastExam.total||0).toFixed(2)} net.`:'Henüz deneme kaydın yok. Deneme Takibi’nden ilk denemeni ekleyebilirsin.';if(/haftalık program.*(göster|ne|plan)|bugün.*program/.test(q))return plan?`Bugünün (${weekday}) haftalık programı: ${plan}`:`${weekday} için kaydedilmiş haftalık programın yok. Haftalık Program sayfasından yazıp kaydedebilirsin.`;if(/bugün.*(hedef|görev)|günlük.*(hedef|görev)/.test(q))return todayTasks.length?`Bugünün ${todayTasks.length} görevi: ${todayTasks.map(x=>x.title).join(' · ')}`:'Bugün için açık görev görünmüyor. Günlük Görevler sayfasından yeni bir hedef ekleyebilirsin.';if(/adın ne|sen kimsin|hangi takımlı|takım tut|kaç yaş|nerelisin/.test(q))return 'Ben Fino; YKS Silkici içindeki eğitim koçuyum 🐾 Takım tutmam ya da kişisel hayatım yok. Amacım çalışma verilerini anlaman, plan yapman ve sınava hazırlanman.';if(/site|uygulama|fino.*(ne yap|nasıl)/.test(q))return 'Ben YKS Silkici’nin eğitim asistanıyım. Notlar, yanlışlar, denemeler, tekrarlar, çalışma süresi, hedefler ve haftalık program hakkında yardımcı olurum. Ne yapmak istediğini yazarsan doğrudan ilgili adımı söyleyeyim.';const allowed=/yks|tyt|ayt|ders|konu|soru|yanlış|deneme|net|çalış|plan|tekrar|hedef|not|program|pomodoro|kronometre|fino|merhaba|selam|nasılsın|motivasyon/.test(q);return allowed?'':'Ben eğitim odaklı bir koçum; bu konuda rastgele bir cevap vermeyeyim. YKS, ders çalışma, deneme, yanlış analizi veya uygulamanın kullanımıyla ilgili bir şey sorabilirsin. 🐾'},
  finoResponse(question){const q=question.toLocaleLowerCase('tr-TR'),direct=this.finoSiteDataAnswer(q);if(direct)return direct;if(/porn|cinsel|seks|çıplak|nü|uyuşturucu|madde sat|silah yap|bomba|intihar|kendime zarar|nefret|ırkçı|küfür|hack|şifre çal|dolandır/.test(q))return 'Bu soruya cevap veremiyorum. İstersen YKS çalışman, günlük planın veya uygulamanın kullanımıyla ilgili bir şey sorabilirsin. 🐾';if(/not.*(ekle|yaz)|not defteri/.test(q))return 'Not Defteri sayfasına girip “Not ekle” düğmesine bas. Dersini ve TYT/AYT türünü seç, konuyu ve notunu yaz; istersen fotoğraf da ekleyebilirsin. Sonrasında filtrelerden ders veya sınav türüne göre notlarını bulursun.';if(/yanlış.*(ekle|kaydet)|yanlış defteri/.test(q))return 'Yanlış Defteri’nde “Yanlış ekle” seçeneğini kullan. TYT/AYT türünü, dersi, konuyu, yanlış mı boş mu bıraktığını ve nedenini yaz. Fino da bu kaydı eksik analizi ile 1-3-7-14 gün tekrar planına dahil eder.';if(/fotoğraf|resim/.test(q))return 'Not ya da yanlış ekleme formundaki fotoğraf alanından görsel seçebilirsin. Eklenen görselin üstüne tıklayınca tamamı açılır; sağ üstte tam ekran ve kapatma seçenekleri vardır.';if(/yedek|indir|yükle|veri/.test(q))return 'Ayarlar sayfasının en altında “Verilerimi indir” ile tüm hesabını JSON yedeği olarak indirirsin. “Verilerimi yükle” ile aynı dosyayı geri yüklersin. Otomatik yerel yedekleme için günlük, haftalık veya yıllık seçeneğini de oradan belirleyebilirsin.';if(/pomodoro|kronometre|süre/.test(q))return 'Pomodoro sayfasında odak ve mola sürelerini başlatabilirsin; Kronometre sayfasında serbest çalışmanı tutup kaydedersin. Kaydedilen süre çalışma ritmine otomatik eklenir ve hafta/ay/yıl analizlerinde görünür.';if(/haftalık program|program.*kaydet/.test(q))return 'Haftalık Program bölümünde her gün için planını yazıp “Programı kaydet” düğmesine bas. Kaydedilen plan aşağıda kalır ve istersen silerek yeniden düzenleyebilirsin.';return this.finoAnswer(question)},
  isFinoInappropriate(question){return /porn|cinsel|seks|çıplak|nü|uyuşturucu|madde sat|silah yap|bomba|intihar|kendime zarar|nefret|ırkçı|küfür|hack|şifre çal|dolandır/.test(question.toLocaleLowerCase('tr-TR'))},
  finoLiveDataAnswer(question){const q=question.toLocaleLowerCase('tr-TR'),u=DB.user(),notes=u.notes||[],mistakes=u.mistakes||[],exams=u.exams||[],tasks=u.tasks||[],subject=Object.keys(Subjects.data).find(s=>q.includes(s.toLocaleLowerCase('tr-TR'))),type=q.includes('ayt')?'AYT':q.includes('tyt')?'TYT':'';const by=(list)=>list.filter(x=>(!type||x.examType===type)&&(!subject||x.subject===subject));if(/not defter|notlarım|kaç not|not.*göster/.test(q)){const list=by(notes),photos=list.filter(x=>x.image).length;return `${type||'Tüm'}${subject?` ${subject}`:''} notlarında ${list.length} kayıt${photos?` ve ${photos} fotoğraf`:' '} var.${list.length?` Son not: “${list.slice().sort((a,b)=>b.createdAt-a.createdAt)[0].title}”.`:' Yeni not eklemek için Not Defteri’ne gidebilirsin.'}`}if(/yanlış defter|yanlışlarım|kaç yanlış|boş.*(soru|bırak)/.test(q)){const list=by(mistakes),wrong=list.filter(x=>x.result==='Yanlış yaptım').length,empty=list.filter(x=>x.result==='Boş bıraktım').length,reasons={};list.forEach(x=>reasons[x.reason]=(reasons[x.reason]||0)+1);const top=Object.entries(reasons).sort((a,b)=>b[1]-a[1])[0];return `${type||'Tüm'}${subject?` ${subject}`:''} yanlış defterinde ${list.length} kayıt var: ${wrong} yanlış, ${empty} boş. ${top?`En sık neden: ${top[0]} (${top[1]} kayıt).`:''}`}if(/deneme.*(kaç|göster|analiz|ortalama)|tyt.*net|ayt.*net/.test(q)){const list=exams.filter(x=>!type||x.examType===type),avg=list.length?list.reduce((a,x)=>a+(+x.total||0),0)/list.length:0,best=list.length?Math.max(...list.map(x=>+x.total||0)):0;return `${type||'Tüm'} denemelerinde ${list.length} kayıt var. Ortalama netin ${avg.toFixed(2)}, en yüksek netin ${best.toFixed(2)}.${list.length?` Son kayıt: ${list.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0].name}.`:''}`}if(/konu.*(ilerleme|yüzde|tamam)|hangi konu/.test(q)){if(subject)return `${subject} konu ilerlemen %${Subjects.progress(subject)}. Konu listesinden durumları “Başlanmadı / Çalışılıyor / Tamamlandı” olarak güncellediğinde bu oran yenilenir.`;const list=Object.keys(Subjects.data).map(s=>({s,p:Subjects.progress(s)})).sort((a,b)=>b.p-a.p);return `Konu ilerlemen en yüksekten düşüğe: ${list.map(x=>`${x.s} %${x.p}`).join(' · ')}.`}if(/hedef.*(bölüm|net)|hedefim/.test(q)){const g=u.goals||{};return g.school||g.targetNet?`Hedefin: ${g.school||'Bölüm belirtilmemiş'} · hedef net ${g.targetNet||'belirtilmemiş'} · mevcut net ${g.currentNet||'belirtilmemiş'}.`:'Henüz hedef eklemedin. Hedeflerim sayfasından bölüm ve net hedefi belirleyebilirsin.'}if(/tamamlanan görev|görev.*tamam|kaç görev/.test(q))return `Görevlerinde ${tasks.filter(x=>x.done).length} tamamlanan, ${tasks.filter(x=>!x.done).length} açık kayıt var.`;return ''},
  finoSmartResponse(question){const live=this.finoLiveDataAnswer(question);return live||this.finoResponse(question)},
  askFino(e){e.preventDefault();const question=Object.fromEntries(new FormData(e.target)).question.trim();if(!question)return;const u=DB.user(),current=this.finoCurrentChat(),answer=this.isFinoInappropriate(question)?'Bu soruya cevap veremiyorum. İstersen YKS çalışman, günlük planın veya uygulamanın kullanımıyla ilgili bir şey sorabilirsin. 🐾':this.finoSmartResponse(question),messages=[...(current.messages||[]),{id:DB.uid(),question,answer,createdAt:Date.now()}].slice(-100),updated={...current,messages,title:(current.messages||[]).length?current.title:question.slice(0,34)};let chats=(u.finoChats||[]).filter(x=>x.id!==current.id);chats.push(updated);DB.update({finoChats:chats.slice(-30),finoActiveChat:updated.id,finoChat:messages});this.render();const list=document.querySelector('.fino-messages');list&&(list.scrollTop=list.scrollHeight)},
  finoAnswer(question){const q=question.toLocaleLowerCase('tr-TR'),u=DB.user(),weak=Analysis.weakTopics(),top=weak[0],reviews=Analysis.reviews(),trend=Analysis.examTrend(),week=Analysis.daily().reduce((sum,x)=>sum+x.value,0),mistakes=u.mistakes||[],exams=u.exams||[];const subject=Object.keys(Subjects.data).find(s=>q.includes(s.toLocaleLowerCase('tr-TR')));const subjectMistakes=subject?mistakes.filter(x=>x.subject===subject):[];let answer;if(/merhaba|selam|nasılsın|naber|günaydın|iyi akşamlar|iyi geceler/.test(q)){answer=`Merhaba ${u.name?.split(' ')[0]||''}! Ben iyiyim, senin hedeflerin için patilerim hazır 🐾 ${top?`Bugün ${top.subject} · ${top.topic} konusuna birlikte odaklanabiliriz.`:'İlk yanlışını veya denemeni eklediğinde sana daha kişisel öneriler vereceğim.'}`}else if(/eks[iı]k|zayıf|nerede|yanlış/.test(q)){if(subject)answer=subjectMistakes.length?`${subject} için ${subjectMistakes.length} yanlış kaydın var. En çok ${subjectMistakes.reduce((map,x)=>(map[x.topic]=(map[x.topic]||0)+1,map),{})&&Object.entries(subjectMistakes.reduce((map,x)=>(map[x.topic]=(map[x.topic]||0)+1,map),{})).sort((a,b)=>b[1]-a[1])[0][0]} üzerinde durmalısın.`:`${subject} için henüz yanlış kaydı yok. Konu eksiğini netleştirmek için bir deneme veya yanlış soru ekle.`;else answer=top?`Şu an en çok zorlandığın alan ${top.subject} · ${top.topic}. Burada ${top.count} kayıt var. Bugün ${top.count>=4?40:30} soru + yanlış analizi en iyi başlangıç olur.`:'Henüz eksik analizi yapacak kadar yanlış kaydın yok. İlk yanlışlarını ekledikçe sana konu bazlı cevap vereceğim.'}else if(/bugün|plan|çalış/.test(q)){answer=top?`Bugünkü planın: önce ${top.subject} ${top.topic} konusundan ${top.count>=4?40:30} soru çöz. ${reviews.length?`Ardından ${reviews[0].subject} ${reviews[0].topic} için tekrar yap; ${reviews.length} tekrar kaydın bekliyor.`:'Sonunda 25 dakikalık kısa bir tekrar turu ekle.'}`:`Bugün 2 adet 25 dakikalık odak turuyla başla. İlk turda soru çöz, ikinci turda çözdüğün soruların yanlışlarını not et.`}else if(/deneme|net|artır/.test(q)){answer=exams.length?`Son deneme trendin ${trend.label.toLocaleLowerCase('tr-TR')}${trend.exams.length>1?` (${trend.delta>0?'+':''}${trend.delta.toFixed(1)} net)`:''}. Net artırmak için en yüksek yanlış kayıtlı konu olan ${top?`${top.subject} ${top.topic}`:'yanlış defterindeki ilk konu'} ile haftada 3 kısa tur yap.`:'Henüz deneme kaydın yok. İlk TYT/AYT denemeni ekle; Fino net trendini ve ders önceliğini çıkaracak.'}else if(/tekrar|hatırla/.test(q)){answer=reviews.length?`Şu an ${reviews.length} tekrar kaydın var. İlk sırada ${reviews[0].subject} · ${reviews[0].topic} bulunuyor; ${reviews[0].day}. gün tekrarı gelmiş. 10-15 dakikada soruyu yeniden çözerek başla.`:'Bugün tekrar süresi gelen yanlış yok. Yeni yanlış ekledikçe 1, 3, 7 ve 14 günlük tekrarlarını ben takip edeceğim.'}else if(/motivasyon|yorul|bıktım/.test(q)){answer=`Bu hafta ${this.duration(week)} çalışma kaydın var. Büyük hedefi değil, sıradaki 25 dakikayı düşün: tek konu, tek kaynak, telefon uzakta. Bitince Fino'ya tekrar yaz.`}else{answer=top?`Verilerine baktım: ${top.subject} · ${top.topic} şu an öncelikli alanın. ${top.count} kayıt ve ${reviews.length} bekleyen tekrarın var. Sorunu biraz daha net yazarsan sana konuya özel bir plan çıkarırım.`:`Seni tanımaya başlıyorum. Deneme, yanlış ve çalışma kaydı ekledikçe cevaplarım tamamen senin verilerine göre değişecek. Şimdilik “Bugün ne çalışmalıyım?” diye sorabilirsin.`}const previous=(u.finoChat||[]).at(-1)?.answer;if(answer===previous)answer+=[' Bir adım seç ve hemen başla.',' İstersen bu görevi Günlük Görevler’e de ekleyebilirsin.',' Bugünün küçük adımı yarının netine dönüşür.'][((u.finoChat||[]).length)%3];return answer},
  addCoachTask(subject,topic,questions=30){const exists=DB.user().tasks.some(t=>t.coach&&t.subject===subject&&t.title.includes(topic)&&!t.done);if(exists)return this.toast('Bu akıllı görev zaten bugünün planında.');DB.update({tasks:[...DB.user().tasks,{id:DB.uid(),title:`${topic} — ${questions} soru çöz`,subject,date:new Date().toISOString().slice(0,10),priority:'Önemli',done:false,coach:true}]});this.toast('Akıllı görev bugünün planına eklendi.');},
  addAllCoachTasks(){const weak=Analysis.weakTopics(),reviews=Analysis.reviews(),items=[];if(weak[0])items.push({subject:weak[0].subject,topic:weak[0].topic,q:weak[0].count>=4?40:30});reviews.slice(0,2).forEach(r=>{if(!items.some(x=>x.topic===r.topic))items.push({subject:r.subject,topic:r.topic,q:15})});items.forEach(x=>this.addCoachTask(x.subject,x.topic,x.q));this.render();},
  subjects(){const u=DB.user();return `<div class="page-title"><div><p class="eyebrow">TÜRKİYE YÜZYILI MAARİF MODELİ</p><h1>TYT Konu Takibi</h1><p>Her konuyu adım adım tamamla, eksiklerini görünür kıl.</p></div></div><div class="subject-grid">${Object.entries(Subjects.data).map(([name,topics])=>{const p=Subjects.progress(name);return `<article class="subject-card glass"><div class="subject-top"><span>${this.subjectIcon(name)}</span><div><h3>${name}</h3><small>${topics.length} konu</small></div><b>%${p}</b></div><div class="progress"><i style="width:${p}%"></i></div><div class="topics">${topics.map(([topic,summary])=>{const s=u.subjects[topic]||'Başlanmadı';return `<button onclick="App.topicModal('${name}','${this.escape(topic)}')"><span class="topic-state ${s==='Tamamlandı'?'complete':s==='Çalışılıyor'?'working':''}">${s==='Tamamlandı'?'✓':s==='Çalışılıyor'?'◐':'○'}</span>${topic}<small>${s}</small></button>`}).join('')}</div></article>`}).join('')}</div>`;},
  aytSubjects(){const u=DB.user();return `<div class="page-title"><div><p class="eyebrow">11. SINIF · TÜRKİYE YÜZYILI MAARİF MODELİ</p><h1>AYT Konu Takibi</h1><p>11. sınıf güncel Maarif Modeli temalarını takip et.</p></div></div><div class="subject-grid">${Object.entries(AytSubjects).map(([name,topics])=>`<article class="subject-card glass"><div class="subject-top"><span>${this.subjectIcon(name)}</span><div><h3>${name}</h3><small>${topics.length} tema</small></div></div><div class="topics">${topics.map(([topic,summary])=>{const s=u.subjects['AYT-'+topic]||'Başlanmadı';return `<button onclick="App.aytTopicModal('${name}','${this.escape(topic)}')"><span class="topic-state ${s==='Tamamlandı'?'complete':s==='Çalışılıyor'?'working':''}">${s==='Tamamlandı'?'✓':s==='Çalışılıyor'?'◐':'○'}</span>${topic}<small>${s}</small></button>`}).join('')}</div></article>`).join('')}</div>`;},
  aytTopicModal(subject,topic){const summary=AytSubjects[subject].find(x=>x[0]===topic)[1],state=DB.user().subjects['AYT-'+topic]||'Başlanmadı';this.modal(topic,`<p class="topic-summary">${summary}</p><label>İlerleme durumu<select onchange="App.setAytTopic('${this.escape(topic)}',this.value)"><option ${state==='Başlanmadı'?'selected':''}>Başlanmadı</option><option ${state==='Çalışılıyor'?'selected':''}>Çalışılıyor</option><option ${state==='Tamamlandı'?'selected':''}>Tamamlandı</option></select></label>`)},
  setAytTopic(topic,status){DB.update({subjects:{...DB.user().subjects,['AYT-'+topic]:status}});this.closeModal();this.render()},
  topicModal(subject,topic){const [,summary]=(Subjects.data[subject].find(x=>x[0]===topic)||[]), state=DB.user().subjects[topic]||'Başlanmadı';this.modal(topic,`<p class="topic-summary">${summary}</p><div class="info-list"><p><b>Önemli bilgiler</b> Konunun temel kavramlarını örnek soru üzerinden ilişkilendir.</p><p><b>Dikkat noktası</b> Yanlış yaptığın soruları yanlış defterine mutlaka not et.</p><p><b>Çalışma önerisi</b> 25 dakika odaklan, ardından 10 soru ile pekiştir.</p></div><label>İlerleme durumu<select onchange="App.setTopic('${this.escape(topic)}',this.value)"><option ${state==='Başlanmadı'?'selected':''}>Başlanmadı</option><option ${state==='Çalışılıyor'?'selected':''}>Çalışılıyor</option><option ${state==='Tamamlandı'?'selected':''}>Tamamlandı</option></select></label>`);},
  setTopic(topic,status){DB.update({subjects:{...DB.user().subjects,[topic]:status}});this.closeModal();this.render();this.toast('Konu durumu güncellendi.');},
  pomodoro(){const s=Pomodoro.state(), rem=Pomodoro.remaining();return `<div class="center-page timer-page"><button class="fullscreen-btn" onclick="App.fullscreen('timer-page')">⛶ Tam ekran</button><p class="eyebrow">DERİN ODAK MODU</p><h1>Pomodoro</h1><p>Çalışmaya başla, zamanı senin yerine biz takip edelim.</p><section class="pomo-card glass"><div class="pomo-ring"><span id="pomo-display">${this.time(rem)}</span><small>${s.active?'ODAKLANIYORSUN':'HAZIR MISIN?'}</small></div><div class="pomo-controls">${s.active?`<button class="btn secondary" onclick="Pomodoro.stop()">Duraklat</button>`:`<button class="btn primary" onclick="Pomodoro.start(${Math.round(rem/60)},true)">Başlat</button>`}<button class="icon-btn" onclick="Pomodoro.reset()">↺</button></div><div class="duration-picker">${[5,10,25,45,60].map(m=>`<button class="${!s.active&&Math.round(rem/60)===m?'selected':''}" onclick="Pomodoro.start(${m})">${m} dk</button>`).join('')}</div></section></div>`;},
  stopwatch(){return `<div class="center-page timer-page"><button class="fullscreen-btn" onclick="App.fullscreen('timer-page')">⛶ Tam ekran</button><p class="eyebrow">SÜREYİ SEN BELİRLE</p><h1>Kronometre</h1><p>Serbest çalışmalarını tek dokunuşla kaydet.</p><section class="pomo-card glass"><div class="pomo-ring stopwatch"><span id="stopwatch-display">${this.time(Stopwatch.value())}</span><small>ÇALIŞMA SÜRESİ</small></div><div class="pomo-controls"><button class="btn primary" onclick="Stopwatch.start()">Başlat</button><button class="btn secondary" onclick="Stopwatch.stop()">Durdur</button><button class="icon-btn" onclick="Stopwatch.reset()">↺</button></div><button class="link-btn" onclick="Stopwatch.save()">✓ Çalışmayı kaydet</button></section></div>`;},
  clock(){return `<div class="center-page timer-page"><button class="fullscreen-btn" onclick="App.fullscreen('timer-page')">⛶ Tam ekran</button><p class="eyebrow">ŞİMDİKİ ZAMAN</p><h1>Canlı Saat</h1><section class="pomo-card glass"><div class="pomo-ring clock"><span id="live-clock">00:00:00</span><small id="live-date">Bugün</small></div><p class="clock-note">Zamanını değil, odağını yönet.</p></section></div>`;},
  notes(){const notes=DB.user().notes||[], subjects=['Tümü',...Object.keys(Subjects.data)];return `<div class="page-title"><div><p class="eyebrow">FİKİRLERİNİ KAÇIRMA</p><h1>Not Defteri</h1><p>Ders notlarını, planlarını ve soru görsellerini tek yerde topla.</p></div><button class="btn primary" onclick="App.noteModal()">+ Yeni not</button></div><div class="filter-row"><input class="search" placeholder="Notlarda ara..." oninput="App.filterNotes()" id="note-search"><select id="note-type-filter" onchange="App.filterNotes()"><option>Tümü</option><option>TYT</option><option>AYT</option></select><select id="note-subject-filter" onchange="App.filterNotes()">${subjects.map(s=>`<option>${s}</option>`).join('')}</select></div><section id="notes-list" class="notes-grid">${this.noteCards(notes)||'<div class="empty glass">Henüz notun yok.</div>'}</section>`;},
  noteCards(notes){return notes.map(n=>`<article class="note-card glass"><div><span class="tag">${this.escape(n.examType||'TYT')} · ${this.escape(n.subject||n.category||'Genel')}</span><button class="star" onclick="Notes.favorite('${n.id}')">${n.favorite?'★':'☆'}</button></div><h3>${this.escape(n.title)}</h3><p>${this.escape(n.content)}</p>${n.image?`<img class="record-image" onclick="App.imageViewer('${n.id}','note')" src="${n.image}" alt="Not görseli">`:''}<footer><small>${new Date(n.createdAt).toLocaleDateString('tr-TR')}</small><button class="icon-btn danger" onclick="Notes.remove('${n.id}')">×</button></footer></article>`).join('');},
  filterNotes(){const q=document.querySelector('#note-search').value.toLowerCase(),s=document.querySelector('#note-subject-filter').value,t=document.querySelector('#note-type-filter').value;const list=DB.user().notes.filter(n=>(n.title+n.content+n.category+(n.subject||'')).toLowerCase().includes(q)&&(s==='Tümü'||n.subject===s)&&(t==='Tümü'||(n.examType||'TYT')===t));document.querySelector('#notes-list').innerHTML=this.noteCards(list)||'<div class="empty glass">Sonuç bulunamadı.</div>';},
  noteModal(){this.modal('Yeni not',`<form onsubmit="Notes.add(event)"><label>Başlık<input name="title" required placeholder="Not başlığı"></label><label>Sınav türü<select name="examType"><option>TYT</option><option>AYT</option></select></label><label>Ders<select name="subject">${Object.keys(Subjects.data).map(s=>`<option>${s}</option>`).join('')}<option>Genel</option></select></label><label>Kategori<select name="category"><option>Ders Notu</option><option>Plan</option><option>Önemli</option><option>Fikir</option></select></label><label>Not<textarea name="content" required placeholder="Aklındakileri yaz..."></textarea></label><label>Fotoğraf ekle <input name="image" type="file" accept="image/*"></label><button class="btn primary wide">Notu kaydet</button></form>`);},
  mistakes(){const a=DB.user().mistakes||[],subjects=['Tümü',...Object.keys(Subjects.data)],reasons=['Tümü','Dikkat eksikliği','Bilgi eksikliği','İşlem hatası','Zaman yönetimi','Soruyu anlamama','Diğer'];return `<div class="page-title"><div><p class="eyebrow">YANLIŞTAN ÖĞREN</p><h1>Yanlış Defteri</h1><p>Yanlışlarını ve boş bıraktıklarını analiz et, tekrarını planla.</p></div><button class="btn primary" onclick="App.mistakeModal()">+ Soru kaydı</button></div><div class="filter-row"><input class="search" id="mistake-search" placeholder="Konu veya notlarda ara..." oninput="App.filterMistakes()"><select id="mistake-type" onchange="App.filterMistakes()"><option>Tümü</option><option>TYT</option><option>AYT</option></select><select id="mistake-subject" onchange="App.filterMistakes()">${subjects.map(s=>`<option>${s}</option>`).join('')}</select><select id="mistake-reason" onchange="App.filterMistakes()">${reasons.map(s=>`<option>${s}</option>`).join('')}</select><select id="mistake-status" onchange="App.filterMistakes()"><option>Tümü</option><option>Yanlış yaptım</option><option>Boş bıraktım</option></select></div><section id="mistakes-list" class="mistake-grid">${this.mistakeCards(a)||'<div class="empty glass">Kaydedilmiş soru yok.</div>'}</section>`;},
  mistakeCards(a){return a.map(m=>`<article class="mistake-card glass ${m.reviewed?'reviewed':''}"><div><span class="tag">${this.escape(m.examType||'TYT')} · ${this.escape(m.subject)}</span><span class="tag">${this.escape(m.result||'Yanlış yaptım')}</span></div><h3>${this.escape(m.topic)}</h3><p><b>Neden:</b> ${this.escape(m.reason)}</p><p>${this.escape(m.note||'Not eklenmemiş.')}</p>${m.image?`<img class="record-image" onclick="App.imageViewer('${m.id}','mistake')" src="${m.image}" alt="Soru görseli">`:''}<footer><button class="link-btn" onclick="Notes.review('${m.id}')">${m.reviewed?'✓ Tekrar edildi':'Tekrar edildi olarak işaretle'}</button><button class="icon-btn danger-icon" title="Kaydı sil" aria-label="Kaydı sil" onclick="Notes.removeMistake('${m.id}')">×</button></footer></article>`).join('');},
  filterMistakes(){const q=(document.querySelector('#mistake-search')?.value||'').toLocaleLowerCase('tr-TR'),type=document.querySelector('#mistake-type').value,subject=document.querySelector('#mistake-subject').value,reason=document.querySelector('#mistake-reason').value,result=document.querySelector('#mistake-status').value;const a=DB.user().mistakes.filter(m=>(`${m.topic} ${m.note||''} ${m.reason}`.toLocaleLowerCase('tr-TR').includes(q))&&(type==='Tümü'||(m.examType||'TYT')===type)&&(subject==='Tümü'||m.subject===subject)&&(reason==='Tümü'||m.reason===reason)&&(result==='Tümü'||m.result===result));document.querySelector('#mistakes-list').innerHTML=this.mistakeCards(a)||'<div class="empty glass">Bu filtreye uygun kayıt yok.</div>';},
  personalNotes(){const list=(DB.user().personalNotes||[]).slice().sort((a,b)=>b.updatedAt-a.updatedAt);return `<div class="page-title"><div><p class="eyebrow">KENDİN İÇİN YAZ</p><h1>Kendime Not</h1><p>Fikirlerini, motivasyonlarını ve unutmak istemediğin şeyleri sakla.</p></div><button class="btn primary" onclick="App.personalNoteModal()">+ Yeni not</button></div><input class="search personal-search" placeholder="Kendi notlarında ara..." oninput="App.filterPersonalNotes()" id="personal-note-search"><section id="personal-notes-list" class="personal-notes-grid">${this.personalNoteCards(list)||'<div class="empty glass">Henüz kendine not yazmadın.</div>'}</section>`;},
  personalNoteCards(list){return list.map(n=>`<article class="personal-note glass"><p>${this.escape(n.content)}</p><footer><small>${new Date(n.updatedAt||n.createdAt).toLocaleString('tr-TR')}</small><div><button class="icon-btn" onclick="App.personalNoteModal('${n.id}')">✎</button><button class="icon-btn danger" onclick="App.deletePersonalNote('${n.id}')">×</button></div></footer></article>`).join('');},
  filterPersonalNotes(){const q=(document.querySelector('#personal-note-search').value||'').toLocaleLowerCase('tr-TR'),list=(DB.user().personalNotes||[]).filter(n=>n.content.toLocaleLowerCase('tr-TR').includes(q));document.querySelector('#personal-notes-list').innerHTML=this.personalNoteCards(list)||'<div class="empty glass">Sonuç bulunamadı.</div>';},
  personalNoteModal(id=''){const note=(DB.user().personalNotes||[]).find(n=>n.id===id);this.modal(note?'Notu düzenle':'Kendime yeni not',`<form onsubmit="App.savePersonalNote(event,'${id}')"><label>Notun<textarea name="content" required placeholder="Bugün kendime şunu hatırlatıyorum...">${this.escape(note?.content||'')}</textarea></label><button class="btn primary wide">${note?'Değişiklikleri kaydet':'Notu kaydet'}</button></form>`);},
  savePersonalNote(e,id=''){e.preventDefault();const content=Object.fromEntries(new FormData(e.target)).content.trim(),list=DB.user().personalNotes||[];const personalNotes=id?list.map(n=>n.id===id?{...n,content,updatedAt:Date.now()}:n):[...list,{id:DB.uid(),content,createdAt:Date.now(),updatedAt:Date.now()}];DB.update({personalNotes});this.closeModal();this.render();this.toast('Kendime not kaydedildi.');},
  deletePersonalNote(id){DB.update({personalNotes:(DB.user().personalNotes||[]).filter(n=>n.id!==id)});this.render();this.toast('Kendime not silindi.');},
  mistakeModal(){this.modal('Yanlış / boş soru kaydı',`<form onsubmit="Notes.addMistake(event)"><label>Sınav türü<select name="examType"><option>TYT</option><option>AYT</option></select></label><label>Ders<select name="subject" required>${Object.keys(Subjects.data).map(s=>`<option>${s}</option>`).join('')}</select></label><label>Konu<input name="topic" required placeholder="Konuyu kendin yaz (örn. Problemler)"></label><label>Soru durumu<select name="result"><option>Yanlış yaptım</option><option>Boş bıraktım</option></select></label><label>Yanlış / boş bırakma nedeni<select name="reason"><option>Dikkat eksikliği</option><option>Bilgi eksikliği</option><option>İşlem hatası</option><option>Zaman yönetimi</option><option>Soruyu anlamama</option><option>Diğer</option></select></label><label>Kendime not<textarea name="note" placeholder="Doğru çözümü, dikkat etmen gerekeni veya tekrar planını yaz..."></textarea></label><label>Soru fotoğrafı ekle<input name="image" type="file" accept="image/*"></label><button class="btn primary wide">Kaydı ekle</button></form>`,'form-modal');},
  exams(){const exams=[...(DB.user().exams||[])].sort((a,b)=>new Date(b.date)-new Date(a.date)),types=['TYT','AYT','Tümü'],summary=t=>{const x=t==='Tümü'?exams:exams.filter(e=>(e.examType||'TYT')===t);return [x.length?x.reduce((a,b)=>a+b.total,0)/x.length:0,x.length?Math.max(...x.map(e=>e.total)):0,x.length]};return `<div class="page-title"><div><p class="eyebrow">GELİŞİMİNİ SAYILARLA GÖR</p><h1>Deneme Takibi</h1><p>TYT ve AYT denemelerini ayrı değerlendir.</p></div><button class="btn primary" onclick="App.examModal()">+ Deneme ekle</button></div><div class="tabs"><button class="selected" onclick="App.filterExams('Tümü',this)">Tümü</button><button onclick="App.filterExams('TYT',this)">TYT</button><button onclick="App.filterExams('AYT',this)">AYT</button></div><section id="exam-list">${this.examContent(exams)}</section><section class="all-time glass"><div class="section-title"><div><p class="eyebrow">TÜM ZAMANLAR</p><h3>TYT, AYT ve toplam sonuçların</h3></div></div><div class="all-time-grid">${types.map(t=>{const s=summary(t);return `<article><b>${t}</b><span>Ortalama net <strong>${s[0].toFixed(1)}</strong></span><span>En yüksek net <strong>${s[1].toFixed(1)}</strong></span><span>Girilen deneme <strong>${s[2]}</strong></span></article>`}).join('')}</div></section>`;},
  examContent(exams){return `<section class="exam-summary">${[['Ortalama net',exams.length?(exams.reduce((a,b)=>a+b.total,0)/exams.length).toFixed(1):'—'],['En yüksek net',exams.length?Math.max(...exams.map(e=>e.total)).toFixed(1):'—'],['Girilen deneme',exams.length]].map(x=>`<article class="glass"><small>${x[0]}</small><strong>${x[1]}</strong></article>`).join('')}</section><section class="glass table-wrap"><table><thead><tr><th>Tür</th><th>Deneme</th><th>Tarih</th><th>Türkçe</th><th>Matematik</th><th>Fen</th><th>Sosyal</th><th>Toplam net</th><th></th></tr></thead><tbody>${exams.map(e=>`<tr><td><span class="tag">${e.examType||'TYT'}</span></td><td><b>${this.escape(e.name)}</b></td><td>${new Date(e.date+'T12:00').toLocaleDateString('tr-TR')}</td>${['turkce','mat','fen','sosyal'].map(k=>`<td>${((+e[k+'D'])-(+e[k+'Y'])/4).toFixed(1)}</td>`).join('')}<td class="net">${e.total.toFixed(2)}</td><td><button class="icon-btn danger" onclick="Exams.remove('${e.id}')">×</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">Henüz deneme sonucu yok.</td></tr>'}</tbody></table></section>`;},
  filterExams(type,button){document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');const x=(DB.user().exams||[]).filter(e=>type==='Tümü'||(e.examType||'TYT')===type).sort((a,b)=>new Date(b.date)-new Date(a.date));document.querySelector('#exam-list').innerHTML=this.examContent(x);},
  examModal(){const fields=['turkce','mat','fen','sosyal'];this.modal('Deneme sonucu ekle',`<form onsubmit="Exams.add(event)"><label>Sınav türü<select name="examType"><option>TYT</option><option>AYT</option></select></label><label>Deneme adı<input name="name" required placeholder="TYT Türkiye Geneli 1"></label><label>Tarih<input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><div class="exam-fields">${fields.map(k=>`<div><b>${{turkce:'Türkçe',mat:'Matematik',fen:'Fen',sosyal:'Sosyal'}[k]}</b><label>Doğru<input name="${k}D" type="number" min="0" value="0"></label><label>Yanlış<input name="${k}Y" type="number" min="0" value="0"></label></div>`).join('')}</div><p class="form-note">Bu denemede en çok zorlandığın konu varsa ekle; Akıllı Koç bunu takip eder.</p><div class="two-cols"><label>Ders<select name="weakSubject"><option value="">Seçme</option>${Object.keys(Subjects.data).map(s=>`<option>${s}</option>`).join('')}</select></label><label>Zorlanılan konu<input name="weakTopic" placeholder="Örn. Problemler"></label></div><button class="btn primary wide">Netleri hesapla ve kaydet</button></form>`);},
  analysis(){const daily=Analysis.daily(), u=DB.user(), questions=(u.tasks||[]).filter(t=>t.done).length*10, subjectScores=Object.keys(Subjects.data).map(s=>({label:s,value:Subjects.progress(s)}));return `<div class="page-title"><div><p class="eyebrow">VERİYLE DAHA AKILLI ÇALIŞ</p><h1>Analiz Merkezi</h1><p>Ritmini, konu ilerlemeni ve net değişimini gör.</p></div></div><div class="stats-grid"><article class="stat-card"><i>◷</i><small>Bu hafta</small><strong>${this.hours(daily.reduce((x,y)=>x+y.value,0))}</strong><span>Çalışma süresi</span></article><article class="stat-card"><i>▤</i><small>Çözülen soru</small><strong>${questions}</strong><span>Tahmini kayıt</span></article><article class="stat-card"><i>↗</i><small>Net ortalaması</small><strong>${Analysis.averageNet().toFixed(1)}</strong><span>Deneme sonuçları</span></article></div><section class="chart-card glass"><div class="section-title"><h3>Haftalık çalışma</h3><small>Saat</small></div>${this.barChart(daily)}</section><section class="chart-card glass"><div class="section-title"><h3>Ders / konu ilerleme</h3><small>Yüzde</small></div>${this.barChart(subjectScores,true)}</section>`;},
  goals(){const g=DB.user().goals||{},target=+g.targetNet||0,current=+g.currentNet||0,p=target?Math.min(100,current/target*100):0,university=g.university||g.school||'Üniversiteni belirle',department=g.department||'Bölümünü belirle';return `<div class="page-title"><div><p class="eyebrow">ROTANI BELİRLE</p><h1>Hedeflerim</h1><p>Hedefini görünür kıl; her gün ona doğru hareket et.</p></div></div><section class="goal-card glass"><div class="goal-orbit">🎯</div><div><small>HEDEF ÜNİVERSİTE</small><h2>${this.escape(university)}</h2><p class="goal-department">${this.escape(department)}</p><div class="goal-nets"><span>Mevcut net <b>${current}</b></span><i></i><span>Hedef net <b>${target||'—'}</b></span></div><div class="progress large"><i style="width:${p}%"></i></div><p class="goal-progress">Hedefinin <b>%${Math.round(p)}</b>'ine ulaştın.</p></div><button class="btn secondary" onclick="App.goalModal()">Hedefi düzenle</button></section>`;},
  goalModal(){const g=DB.user().goals||{};this.modal('Hedefini düzenle',`<form onsubmit="App.saveGoal(event)"><label>Hedef üniversite<input name="university" value="${this.escape(g.university||g.school||'')}" placeholder="Örn. Boğaziçi Üniversitesi"></label><label>Hedef bölüm<input name="department" value="${this.escape(g.department||'')}" placeholder="Örn. Bilgisayar Mühendisliği"></label><div class="two-cols"><label>Hedef net<input name="targetNet" type="number" min="0" value="${g.targetNet||''}"></label><label>Mevcut net<input name="currentNet" type="number" min="0" value="${g.currentNet||''}"></label></div><button class="btn primary wide">Hedefi kaydet</button></form>`);},
  saveGoal(e){e.preventDefault();DB.update({goals:Object.fromEntries(new FormData(e.target))});this.closeModal();this.render();},
  settings(){const u=DB.user(),freq=u.backupFrequency||'weekly';return `<div class="page-title"><div><p class="eyebrow">HESABIN</p><h1>Ayarlar</h1><p>YKS Silkici deneyimini kendine göre düzenle.</p></div></div><section class="settings-card glass"><h3>Profil bilgileri</h3><p class="form-note">Toplulukta yalnızca kullanıcı adın ve seçtiğin profil fotoğrafın görünür.</p><div class="settings-actions"><button class="btn secondary" onclick="Social.changeAvatar()">◉ Profil fotoğrafı ekle / değiştir</button></div><form onsubmit="App.saveSettings(event)"><label>Adın<input name="name" value="${this.escape(u.name)}"></label><label>Kullanıcı adı<input value="${this.escape(u.username)}" disabled></label><button class="btn primary">Değişiklikleri kaydet</button></form></section><section class="settings-card glass"><h3>Verilerin ve yedeklerin</h3><p>İndirilen yedek; görev, not, yanlış, deneme, çalışma süresi, konu ilerlemesi ve hedeflerin dahil tüm hesabını içerir.</p><div class="settings-actions"><button class="btn secondary" onclick="App.exportData()">↓ Verilerimi indir</button><button class="btn secondary" onclick="document.querySelector('#import-backup').click()">↑ Verilerimi yükle</button><input id="import-backup" class="hidden" type="file" accept="application/json" onchange="App.importData(event)"></div><label>Otomatik yerel yedekleme<select onchange="App.setBackupFrequency(this.value)"><option value="daily" ${freq==='daily'?'selected':''}>Günlük</option><option value="weekly" ${freq==='weekly'?'selected':''}>Haftalık</option><option value="yearly" ${freq==='yearly'?'selected':''}>Yıllık</option></select></label><small class="settings-help">Otomatik yedek, seçtiğin sıklıkta bu cihazda saklanır. İstersen üstteki indirme ile ayrıca dosya olarak alabilirsin.</small></section>`;},
  saveSettings(e){e.preventDefault();DB.update({name:Object.fromEntries(new FormData(e.target)).name});this.render();this.toast('Profil güncellendi.');},
  exportData(){const blob=new Blob([JSON.stringify({app:'YKS Silkici',version:2,exportedAt:new Date().toISOString(),data:DB.user()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`yks-silkici-yedek-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);},
  importData(e){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),data=parsed.data||parsed;if(!data||typeof data!=='object'||!Array.isArray(data.tasks))throw new Error();DB.update({...data,username:DB.user().username,password:DB.user().password});this.toast('Yedek başarıyla yüklendi.');this.render()}catch{this.toast('Bu geçerli bir YKS Silkici yedek dosyası değil.')}};reader.readAsText(file)},
  setBackupFrequency(value){DB.update({backupFrequency:value});this.createAutoBackup(true);this.toast('Otomatik yerel yedekleme ayarı kaydedildi.')},
  createAutoBackup(force=false){const u=DB.user();if(!u)return;const frequency=u.backupFrequency||'weekly',ms={daily:864e5,weekly:6048e5,yearly:31536e6}[frequency],last=+u.lastAutoBackup||0;if(force||Date.now()-last>=ms){localStorage.setItem(`yks-silkici-auto-backup-${u.username}`,JSON.stringify({savedAt:Date.now(),data:u}));DB.update({lastAutoBackup:Date.now()})}},
  barChart(data,percent=false,showValues=false){const max=Math.max(...data.map(x=>x.value),1);return `<div class="bars">${data.map(x=>`<div>${showValues?`<b class="bar-value">${this.hours(x.value)}</b>`:''}<span style="height:${Math.max(5,x.value/max*100)}%" title="${percent?x.value+'%':this.hours(x.value)}"></span><small>${x.label}</small></div>`).join('')}</div>`;},
  subjectIcon(n){return ({'Türkçe':'Aa','Matematik':'∑','Geometri':'△','Fizik':'⚛','Kimya':'⚗','Biyoloji':'♧','Tarih':'⌛','Coğrafya':'◎','Felsefe':'☁','Din Kültürü':'☾'})[n]||'◉';},
  quote(){const day=Math.floor(Date.now()/86400000),q=this.quotes;return q[day%q.length]+' '+['Bugün başla.','Yolun açık.','Devam et.','Bunu yapabilirsin.','Bir adım daha.','Gücün sende.','Şimdi odaklan.','Kendin için.','Vazgeçme.','İnan ve ilerle.'][Math.floor(day/q.length)%10];},
  newQuote(){const e=document.querySelector('#quote-text');if(e){this.quotes.push(this.quotes.shift());e.textContent=this.quote();}},
  countdown(){const update=()=>{const d=Math.max(0,new Date('2028-06-18T10:15:00+03:00')-Date.now()),x=[Math.floor(d/864e5),Math.floor(d/36e5)%24,Math.floor(d/6e4)%60,Math.floor(d/1e3)%60],el=document.querySelector('#countdown'),days=document.querySelector('#days-left');if(el)el.innerHTML=x.map((v,i)=>`<b>${String(v).padStart(2,'0')}<small>${['GÜN','SAAT','DK','SN'][i]}</small></b>`).join('');if(days)days.textContent=`${x[0]} gün kaldı`;};update();clearInterval(this.countdownTimer);this.countdownTimer=setInterval(update,1000);},
  runClock(){const update=()=>{const now=new Date(),clock=document.querySelector('#live-clock'),date=document.querySelector('#live-date');if(clock)clock.textContent=now.toLocaleTimeString('tr-TR');if(date)date.textContent=now.toLocaleDateString('tr-TR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});};update();clearInterval(this.clockTimer);this.clockTimer=setInterval(update,1000);},
  fullscreen(className){const el=document.querySelector('.'+className);if(!document.fullscreenElement)el.requestFullscreen?.();else document.exitFullscreen?.();},
  imageData(input){return new Promise(resolve=>{const file=input?.files?.[0];if(!file)return resolve('');if(file.size>1800000){this.toast('Fotoğraf en fazla 1.8 MB olmalı.');return resolve('');}const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file);});},
  imageViewer(id,type){const item=(type==='note'?DB.user().notes:DB.user().mistakes).find(x=>x.id===id);if(!item?.image)return;document.querySelector('#modal-root').innerHTML=`<div class="image-viewer"><button class="viewer-fullscreen" onclick="App.viewerFullscreen()">⛶</button><button class="viewer-close" onclick="App.closeModal()">×</button><img src="${item.image}" alt="Tam soru görseli"></div>`;},
  viewerFullscreen(){const e=document.querySelector('.image-viewer');if(!document.fullscreenElement)e?.requestFullscreen?.();else document.exitFullscreen?.();},
  studyStats(){const logs=DB.user().studyLogs||[],now=Date.now(),calc=days=>logs.filter(l=>new Date(l.date)>=new Date(now-days*864e5)).reduce((a,l)=>a+(+l.minutes||0),0),w=calc(7),m=calc(30),y=calc(365);this.modal('Çalışma süresi özeti',`<section class="study-summary"><article><button onclick="App.studyGraph(7)"><small>SON 7 GÜN</small><strong>${this.hours(w)}</strong><span>Grafik ve günlük düzenleme →</span></button></article><article><button onclick="App.studyGraph(30)"><small>SON 30 GÜN</small><strong>${this.hours(m)}</strong><span>Grafik ve günlük düzenleme →</span></button></article><article><button onclick="App.studyGraph(365)"><small>SON 1 YIL</small><strong>${this.hours(y)}</strong><span>Aylara göre grafik →</span></button></article></section>`);},
  studyGraph(days){const now=new Date(),title=days===7?'Haftalık':days===30?'Aylık':'Yıllık';if(days===365){const years=[now.getFullYear()-2,now.getFullYear()-1,now.getFullYear()];this.modal('Yıllık çalışma özeti',`<div class="year-tabs">${years.map(y=>`<button class="btn secondary" onclick="App.yearTable(${y})">${y}</button>`).join('')}</div><p class="form-note">Bir yılı seçerek aylara göre çalışma süresini ve ortalamasını gör.</p>`);return}const data=Analysis.range(days),isWeek=days===7;this.modal(`${title} çalışma çizelgesi`, `<div class="graph-toolbar">${isWeek?'<div><b>Bu hafta</b><p class="form-note">Günlük çalışma sürelerin</p></div>':`<div><label>Ay<select onchange="App.monthTable(this.value)">${Array.from({length:12},(_,i)=>`<option value="${i}" ${i===now.getMonth()?'selected':''}>${new Date(2026,i,1).toLocaleDateString('tr-TR',{month:'long'})}</option>`).join('')}</select></label></div>`}<button class="btn primary" onclick="App.addStudyLog()">+ Süre ekle</button></div><p class="form-note">Her kutu bir günü gösterir. Kalemle düzenle, çarpıyla tamamen sil.</p><section class="month-grid ${isWeek?'week-grid':''}">${data.map(x=>`<article><b>${isWeek?x.label:x.label+'. gün'}</b><strong>${this.duration(x.value)}</strong><div><button class="icon-btn" onclick="App.editLogDay('${x.date}',${x.value},${days})">✎</button><button class="icon-btn danger" onclick="App.saveLogDay('${x.date}',0,${days})">×</button></div></article>`).join('')}</section>`);},
  monthTable(month){const d=new Date();d.setMonth(+month);const data=[];for(let i=1;i<=30;i++){const date=new Date(d.getFullYear(),d.getMonth(),i),key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`,value=(DB.user().studyLogs||[]).filter(l=>String(l.date).slice(0,10)===key).reduce((a,l)=>a+(+l.minutes||0),0);data.push({date:key,label:i,value})}this.modal(`${d.toLocaleDateString('tr-TR',{month:'long',year:'numeric'})} çalışma çizelgesi`, `<div class="graph-toolbar"><button class="btn secondary" onclick="App.studyGraph(30)">← Ay seç</button><div><button class="btn secondary" onclick="App.modalFullscreen()">⛶ Tam ekran</button><button class="btn primary" onclick="App.addStudyLog()">+ Süre ekle</button></div></div><p class="form-note">30 günlük geniş çizelgede günleri düzenleyebilir, çarpıyla o günün tüm süresini silebilirsin.</p><section class="month-grid">${data.map(x=>`<article><b>${x.label}. gün</b><strong>${this.duration(x.value)}</strong><div><button class="icon-btn" onclick="App.editLogDay('${x.date}',${x.value},30,${+month})">✎</button><button class="icon-btn danger" onclick="App.saveLogDay('${x.date}',0,30,${+month})">×</button></div></article>`).join('')}</section>`, 'wide-modal');},
  yearTable(year){const months=Array.from({length:12},(_,i)=>{const value=(DB.user().studyLogs||[]).filter(l=>{const d=new Date(l.date);return d.getFullYear()===year&&d.getMonth()===i}).reduce((a,l)=>a+(+l.minutes||0),0);return {label:new Date(year,i,1).toLocaleDateString('tr-TR',{month:'long'}),value}}),total=months.reduce((a,x)=>a+x.value,0);this.modal(`${year} yıllık çalışma çizelgesi`, `<p class="form-note">Toplam: ${this.duration(total)} · Aylık ortalama: ${this.duration(Math.round(total/12))}</p><section class="year-grid">${months.map(x=>`<article><b>${x.label}</b><strong>${this.duration(x.value)}</strong></article>`).join('')}</section>`);},
  editLogDay(date,minutes,days,month=null){this.modal('Günlük süreyi düzenle',`<form onsubmit="App.editLogSubmit(event,'${date}',${days},${month===null?'null':month})"><div class="two-cols"><label>Saat<input name="hours" type="number" min="0" value="${Math.floor(minutes/60)}"></label><label>Dakika<input name="minutes" type="number" min="0" max="59" value="${minutes%60}"></label></div><button class="btn primary wide">Kaydet</button></form>`)},
  editLogSubmit(e,date,days,month=null){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));this.saveLogDay(date,(+f.hours||0)*60+(+f.minutes||0),days,month)},
  modalFullscreen(){const e=document.querySelector('.modal');if(!document.fullscreenElement)e?.requestFullscreen?.();else document.exitFullscreen?.()},
  toggleLogEdit(){document.querySelector('#log-editor')?.classList.toggle('hidden')},
  saveLogDay(date,minutes,days,month=null){const logs=(DB.user().studyLogs||[]).filter(l=>String(l.date).slice(0,10)!==date);if(+minutes>0)logs.push({id:DB.uid(),minutes:+minutes,date:date+'T12:00:00'});DB.update({studyLogs:logs});month===null?this.studyGraph(days):this.monthTable(month);this.toast(+minutes?'Günlük süre güncellendi.':'Günlük süre sıfırlandı.')},
  addStudyLog(){this.modal('Çalışma süresi ekle',`<form onsubmit="App.saveManualLog(event)"><label>Tarih<input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><div class="two-cols"><label>Saat<input name="hours" type="number" min="0" value="0"></label><label>Dakika<input name="minutes" type="number" min="0" max="59" value="0"></label></div><button class="btn primary wide">Kaydet</button></form>`)},
  saveManualLog(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),total=(+f.hours||0)*60+(+f.minutes||0);if(!total)return this.toast('En az 1 dakika gir.');DB.update({studyLogs:[...(DB.user().studyLogs||[]),{id:DB.uid(),minutes:total,date:f.date+'T12:00:00'}]});this.closeModal();this.toast('Çalışma süresi eklendi.')},
  time(seconds){seconds=Math.max(0,seconds||0);return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(x=>String(x).padStart(2,'0')).join(':');},
  duration(m){return m>=60?`${Math.floor(m/60)} sa ${m%60} dk`:`${m} dk`;},
  hours(m){return `${(m/60).toFixed(m%60?1:0)} sa`;},
  modal(title,html,extraClass=''){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="App.closeModal(event)"><section class="modal ${extraClass}" onclick="event.stopPropagation()"><header><h2>${title}</h2><button class="icon-btn" onclick="App.closeModal()">×</button></header>${html}</section></div>`;},
  closeModal(e){if(e&&e.target!==e.currentTarget)return;if(document.fullscreenElement)document.exitFullscreen?.();document.querySelector('#modal-root').innerHTML='';},
  toast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>e.classList.remove('show'),2800);},
  toggleMenu(){document.querySelector('.sidebar').classList.toggle('open');},
  escape(s){return String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]));}
};
document.addEventListener('DOMContentLoaded',()=>{App.init();App.countdown();});
